`/// POST /open - idempotently moves a Submitted application to UnderReview
/// and returns the post-transition status slug.
pub fn mark_opened(
  store: DemoStore,
  vacancy_id: String,
  application_id: String,
) -> #(DemoStore, Result(String, Nil)) {
  change_status(
    store,
    vacancy_id,
    application_id,
    "under_review",
    "status_auto_changed",
  )
}` — change_status sets `status: target` on whatever the current status is, with no Submitted guard.

`fn status_from_slug(slug: String) -> ApplicationStatus {
  case slug {
    "submitted" -> Submitted
    "under_review" -> UnderReview
    "shortlisted" -> Shortlisted
    "viewed" -> Viewed
    "approved" -> Approved
    "rejected" -> Rejected
    _ -> Submitted
  }
}`

